  }
  const firstChar = label[Symbol.iterator]().next().value;
  if (/\p{M}/u.test(firstChar)) {
    throw new IDNAError('Label begins with an illegal combining character');
  }
  let position = 0;
  for (const ch of label) {
    position += 1;
    const cp = ch.codePointAt(0);
    let ok;
    if (cp < 0x80) {
      ok =
        (cp >= 0x30 && cp <= 0x39) || // 0-9
        (cp >= 0x41 && cp <= 0x5a) || // A-Z
        (cp >= 0x61 && cp <= 0x7a) || // a-z
        cp === 0x2d; // '-'
