      // Non-ASCII: PVALID per IDNA2008 (categories Ll/Lo/Lm/Mn/Mc/Nd and
      // stable under NFKC), plus CONTEXTJ joiners U+200C / U+200D.
      ok =
        cp === 0x200c ||
        cp === 0x200d ||
