import {
  IDNAError,
  InvalidCodepoint,
  alabel,
  ulabel,
  idnaEncode,
  idnaDecode,
} from '/output/idna.mjs';

let failures = 0;
function eq(actual, expected, name) {
  if (actual === expected) {
    console.log(`PASS ${name}`);
  } else {
    failures++;
    console.log(`FAIL ${name}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
}
function roundTrip(domain) {
  try {
    const enc = idnaEncode(domain);
    const dec = idnaDecode(enc);
    if (dec === domain) {
      console.log(`PASS roundtrip ${domain} -> ${enc}`);
    } else {
      failures++;
      console.log(`FAIL roundtrip ${domain}: decode gave ${JSON.stringify(dec)}`);
    }
    return enc;
  } catch (e) {
    failures++;
    console.log(`FAIL roundtrip ${domain}: threw ${e.name}: ${e.message}`);
    return null;
  }
}
// exactMsg: exact full message; notCodepoint: require plain IDNAError, not InvalidCodepoint
function throwsExact(fn, exactMsg, name, { notCodepoint = false } = {}) {
  try {
    fn();
    failures++;
    console.log(`FAIL ${name}: did not throw`);
  } catch (e) {
    if (!(e instanceof IDNAError)) {
      failures++;
      console.log(`FAIL ${name}: threw ${e.name} (not IDNAError): ${e.message}`);
    } else if (notCodepoint && e instanceof InvalidCodepoint) {
      failures++;
      console.log(`FAIL ${name}: threw InvalidCodepoint, expected plain IDNAError: ${e.message}`);
    } else if (e.message !== exactMsg) {
      failures++;
      console.log(`FAIL ${name}: message ${JSON.stringify(e.message)} !== ${JSON.stringify(exactMsg)}`);
    } else {
      console.log(`PASS ${name} (${e.name}: ${e.message})`);
    }
  }
}

// ---- original suite ----
eq(alabel('café'), 'xn--caf-dma', "alabel('café')");
eq(ulabel('xn--caf-dma'), 'café', "ulabel('xn--caf-dma')");
eq(alabel('EXAMPLE'), 'EXAMPLE', "alabel('EXAMPLE') keeps case");
eq(ulabel('EXAMPLE'), 'example', "ulabel('EXAMPLE') lowercases");
eq(ulabel('XN--CAF-DMA'), 'café', "ulabel('XN--CAF-DMA')");
eq(idnaEncode('программирование.рф'), 'xn--80aafcnpc2aandfgoce.xn--p1ai', 'encode russian');
eq(idnaDecode('xn--80aafcnpc2aandfgoce.xn--p1ai'), 'программирование.рф', 'decode russian');
eq(idnaEncode('example。com'), 'example.com', 'unicode dot U+3002');
eq(idnaEncode('a．b｡c'), 'a.b.c', 'unicode dots U+FF0E U+FF61');
eq(idnaEncode('EXAMPLE.com'), 'EXAMPLE.com', 'encode keeps ASCII case');
eq(idnaDecode('EXAMPLE.com'), 'example.com', 'decode lowercases ASCII');
eq(idnaDecode('xn--caf-dma.fr'), 'café.fr', 'decode punycode label');
eq(idnaDecode('café.fr'), 'café.fr', 'decode unicode passthrough');
throwsExact(() => alabel('foo_bar'), "Codepoint U+005F at position 4 of 'foo_bar' not allowed", 'alabel invalid codepoint');
throwsExact(() => idnaEncode('foo_bar.com'), "Codepoint U+005F at position 4 of 'foo_bar' not allowed", 'encode invalid codepoint');
throwsExact(() => idnaEncode(''), 'Empty domain', 'empty domain encode');
throwsExact(() => idnaDecode(''), 'Empty domain', 'empty domain decode');
throwsExact(() => idnaEncode('...'), 'Empty domain', 'all dots');
throwsExact(() => idnaEncode('a..b'), 'Empty Label', 'empty middle label');
throwsExact(() => idnaEncode('-abc.com'), 'Label must not start or end with a hyphen', 'leading hyphen');
throwsExact(() => idnaEncode('abc-.com'), 'Label must not start or end with a hyphen', 'trailing hyphen');
throwsExact(() => idnaEncode('a'.repeat(64) + '.com'), 'Label too long', 'label too long');
throwsExact(() => idnaEncode('é'.repeat(100)), 'Label too long', 'punycode label too long');
throwsExact(() => idnaEncode('a b.com'), "Codepoint U+0020 at position 2 of 'a b' not allowed", 'space in label');
throwsExact(() => ulabel('xn--zzzzzz'), 'Invalid A-label', 'invalid punycode decode');
eq(idnaEncode('example.com.'), 'example.com.', 'trailing dot preserved on encode');
eq(idnaDecode('example.com.'), 'example.com.', 'trailing dot preserved on decode');
eq(idnaEncode('.example.com'), 'example.com', 'leading dot stripped');
const longLabel = 'a'.repeat(63);
throwsExact(() => idnaEncode([longLabel, longLabel, longLabel, longLabel].join('.')), 'Domain too long', 'domain too long');
eq(idnaEncode([longLabel, longLabel, longLabel].join('.')), [longLabel, longLabel, longLabel].join('.'), '191-char domain ok');

// ---- new: strict non-ASCII checkLabel ----
throwsExact(() => idnaEncode('ﬀ.com'), "Codepoint U+FB00 at position 1 of 'ﬀ' not allowed", 'U+FB00 ligature');
throwsExact(() => idnaEncode('①②③.com'), "Codepoint U+2460 at position 1 of '①②③' not allowed", 'U+2460 circled digit');
throwsExact(() => idnaEncode('É.com'), "Codepoint U+00C9 at position 1 of 'É' not allowed", 'U+00C9 uppercase');
throwsExact(() => idnaEncode('ẞ.de'), "Codepoint U+1E9E at position 1 of 'ẞ' not allowed", 'U+1E9E capital sharp s');
throwsExact(() => idnaEncode('ℌ𝔎.com'), "Codepoint U+210C at position 1 of 'ℌ𝔎' not allowed", 'U+210C fraktur');
throwsExact(() => idnaEncode('Ⅷ.com'), "Codepoint U+2167 at position 1 of 'Ⅷ' not allowed", 'U+2167 roman numeral');
throwsExact(() => idnaEncode('é.com'), "Label must be in Normalization Form C", 'non-NFC label', { notCodepoint: true });
throwsExact(() => idnaEncode('́x.com'), 'Label begins with an illegal combining character', 'leading combining mark', { notCodepoint: true });

// ---- new: must-still-pass regression round trips ----
eq(idnaEncode('café.fr'), 'xn--caf-dma.fr', 'exact café.fr');
eq(idnaEncode('straße.de'), 'xn--strae-oqa.de', 'exact straße.de');
eq(idnaEncode('bücher.de'), 'xn--bcher-kva.de', 'exact bücher.de');
roundTrip('προγραμματισμός.gr');
roundTrip('café.fr');
roundTrip('программирование.рф');
roundTrip('సాంకేతికతłęь.in');
roundTrip('日本語.jp');
roundTrip('مثال.إختبار');
roundTrip('उदाहरण.भारत');
roundTrip('中華電信.tw');
roundTrip('straße.de');
roundTrip('bücher.de');

// subclass hierarchy
try { alabel('foo_bar'); } catch (e) {
  if (e instanceof InvalidCodepoint && e instanceof IDNAError && e instanceof Error) {
    console.log('PASS InvalidCodepoint subclass hierarchy');
  } else { failures++; console.log('FAIL subclass hierarchy'); }
}

console.log(failures === 0 ? '\nALL TESTS PASSED' : `\n${failures} FAILURE(S)`);
process.exit(failures === 0 ? 0 : 1);
